local HarpMaker = {}
local PRODUCTS = {
    lyre = { name = "Lira", woodCost = 2, gutCost = 2, time = 2, cost = 30, soundQuality = 8, prestige = 1, description = "Preprosta lira za potujoče pevce." },
    small_harp = { name = "Mala harfa", woodCost = 3, gutCost = 3, time = 4, cost = 90, soundQuality = 12, prestige = 3, description = "Mala harfa z 12 strunami." },
    gut_harp = { name = "Črevesna harfa", woodCost = 4, gutCost = 4, time = 6, cost = 220, soundQuality = 16, prestige = 6, happiness = 1, description = "Harfa s črevesnimi strunami." },
    wire_harp = { name = "Žična harfa", woodCost = 4, brassCost = 2, gutCost = 2, time = 8, cost = 480, soundQuality = 20, prestige = 11, happiness = 2, description = "Irsta harfa z medeninastimi strunami." },
    silver_harp = { name = "Srebrna harfa", woodCost = 4, silverCost = 2, brassCost = 1, time = 11, cost = 950, soundQuality = 26, prestige = 18, happiness = 4, description = "Srebrna harfa za plemiške dvorane." },
    royal_gold_harp = { name = "Kraljevska zlata harfa", woodCost = 5, goldCost = 2, silverCost = 2, jewelCost = 1, gutCost = 3, time = 15, cost = 2200, soundQuality = 38, prestige = 50, happiness = 10, description = "Velika kraljevska harfa z zlatim okvirjem in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Hafarska delavnica", cost = { gold = 260, wood = 130 }, upkeep = 6, qualityBonus = 5 },
    stringing_room = { name = "Strunarska soba", cost = { gold = 800, wood = 220, stone = 200, gut = 8 }, upkeep = 20, qualityBonus = 18 },
    sounding_room = { name = "Zvočna soba", cost = { gold = 1700, wood = 280, stone = 350, silver = 25, brass = 8 }, upkeep = 40, qualityBonus = 30 },
    royal_harp_atelier = { name = "Kraljevski atelje harf", cost = { gold = 6500, wood = 500, stone = 700, gold = 50, silver = 30 }, upkeep = 120, qualityBonus = 55, prestigeBonus = 30 },
}
HarpMaker.woodStock = 16; HarpMaker.gutStock = 12; HarpMaker.brassStock = 8; HarpMaker.silverStock = 6; HarpMaker.goldStock = 6; HarpMaker.jewelStock = 4
HarpMaker.productStock = {}; HarpMaker.buildings = {}; HarpMaker.maker = nil; HarpMaker.activeMaking = {}; HarpMaker.totalProducts = 0; HarpMaker.dayTimer = 0
function HarpMaker.init() HarpMaker.woodStock=16; HarpMaker.gutStock=12; HarpMaker.brassStock=8; HarpMaker.silverStock=6; HarpMaker.goldStock=6; HarpMaker.jewelStock=4; HarpMaker.productStock={}; HarpMaker.buildings={}; HarpMaker.maker=nil; HarpMaker.activeMaking={}; HarpMaker.totalProducts=0; HarpMaker.dayTimer=0; print("[HarpMaker] Royal Harp Maker System initialized (6 products, 4 buildings)") end
function HarpMaker.hireMaker(n,s) s=s or math.random(50,90); local c=470+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HarpMaker.maker={name=n or ("Harfar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Harfar najet: %s (spretnost: %d)",HarpMaker.maker.name,s),"success") end; return true end
function HarpMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HarpMaker.build(id) local ok,e=HarpMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HarpMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HarpMaker.getQualityBonus() local b=0; for _,bd in ipairs(HarpMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HarpMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and HarpMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.gutCost and HarpMaker.gutStock<(d.gutCost or 0) then return false,"Premalo črevesja" end; if d.brassCost and HarpMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and HarpMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HarpMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HarpMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #HarpMaker.buildings==0 then return false,"Potrebna delavnica" end; if not HarpMaker.maker then return false,"Potreben harfar" end; return true end
function HarpMaker.make(pt,qty) qty=qty or 1; local ok,e=HarpMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then HarpMaker.woodStock=HarpMaker.woodStock-d.woodCost*qty end; if d.gutCost then HarpMaker.gutStock=HarpMaker.gutStock-d.gutCost*qty end; if d.brassCost then HarpMaker.brassStock=HarpMaker.brassStock-d.brassCost*qty end; if d.silverCost then HarpMaker.silverStock=HarpMaker.silverStock-d.silverCost*qty end; if d.goldCost then HarpMaker.goldStock=HarpMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HarpMaker.jewelStock=HarpMaker.jewelStock-d.jewelCost*qty end; local t=d.time; if HarpMaker.maker then t=math.max(1,t-math.floor(HarpMaker.maker.skill/12)) end; table.insert(HarpMaker.activeMaking,{id="harp_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,soundQuality=d.soundQuality or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HarpMaker.completeMaking(m) local q=1.0+(HarpMaker.getQualityBonus()/100); if HarpMaker.maker then q=q+(HarpMaker.maker.skill/180) end; q=math.min(2.0,q); HarpMaker.productStock[m.productType]=(HarpMaker.productStock[m.productType] or 0)+m.quantity; HarpMaker.totalProducts=HarpMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HarpMaker.maker then HarpMaker.maker.itemsMade=HarpMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then HarpMaker.maker.skill=math.min(100,HarpMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Harfa izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"harp.completed",{productName=m.productName,soundQuality=m.soundQuality}) end end
function HarpMaker.update(dt) if not _G.state then return end; HarpMaker.dayTimer=HarpMaker.dayTimer+dt; if HarpMaker.dayTimer>=30 then HarpMaker.dayTimer=0; for i=#HarpMaker.activeMaking,1,-1 do local m=HarpMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HarpMaker.completeMaking(m); table.remove(HarpMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HarpMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HarpMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HarpMaker.getStats() return {woodStock=HarpMaker.woodStock,gutStock=HarpMaker.gutStock,brassStock=HarpMaker.brassStock,silverStock=HarpMaker.silverStock,goldStock=HarpMaker.goldStock,jewelStock=HarpMaker.jewelStock,productStock=HarpMaker.productStock,numBuildings=#HarpMaker.buildings,hasMaker=HarpMaker.maker~=nil,makerName=HarpMaker.maker and HarpMaker.maker.name or "—",makerSkill=HarpMaker.maker and HarpMaker.maker.skill or 0,activeMaking=#HarpMaker.activeMaking,totalProducts=HarpMaker.totalProducts} end
return HarpMaker
